//! OpenAPI 描述实际注册的能力；尚未接入的策略提交不列为可用端点。
use axum::{Json,response::Html};
use wavequant_quant_rs::indexed_json::{Value,json};
pub async fn specification()->Json<Value> {
    let mut paths=wavequant_quant_rs::indexed_json::Map::new();
    for (path,summary,required,optional) in [
        ("/health/live","进程存活",&[][..],&[][..]),
        ("/health","用户 PostgreSQL 健康状态",&[][..],&[][..]),
        ("/api/infrastructure/health","研究 SQL 与 Redis 健康状态",&[][..],&[][..]),
        ("/api/research-config","轻量研究配置，不读取日线或交易日列表",&[][..],&[][..]),
        ("/api/catalog","封存研究目录",&[][..],&[][..]),
        ("/api/health","指定封存研究的完整性与运行状态",&["run"][..],&[][..]),
        ("/api/view","封存 strict/proxy 组合视图",&["run","variant","symbol","asof","scenario"][..],&[][..]),
        ("/api/stock-view","封存前缀上的原生独立个股账户",&["run","variant","symbol","asof","scenario"][..],&["n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/stock-summary","各股票独立账户的真实结果汇总",&["run","variant","asof","scenario"][..],&[][..]),
        ("/api/theory","封存前缀对应的统一结构与事件投影",&["run","variant","symbol","asof"][..],&["n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/market-timeframe","相同周期行情与原生趋势快照",&["source","symbol","asof","timeframe"][..],&["n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/tdx-theory","通达信原始行情结构投影",&["symbol","asof"][..],&["timeframe","n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/akshare-theory","新浪同源原始行情结构投影",&["symbol","asof"][..],&["timeframe","n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/tdx-catalog","本地 TDX 证券目录",&[][..],&[][..]),
        ("/api/akshare-catalog","沪深北证券目录与交易日历",&[][..],&[][..]),
        ("/api/tdx-view","TDX 原始不复权行情",&["symbol","asof"][..],&["timeframe"][..]),
        ("/api/akshare-view","原生新浪同源不复权行情",&["symbol","asof"][..],&["timeframe"][..]),
        ("/api/trend-bars","趋势计算使用的同版本独立复权行情快照",&["data_version"][..],&[][..]),
        ("/api/market-bars","带版本约束的年度行情分页",&["source","symbol","asof","timeframe"][..],&["year","data_version"][..]),
        ("/api/structure-signals","已原子发布的结构信号读模型",&["run","variant","source","asof","lookback","signal_type","trend_level"][..],&["symbol","markets","n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/buy-signals","已原子发布的买点信号读模型",&["run","variant","scenario","source","asof","start","lookback"][..],&["symbol","n_target_trend_confirmation_enabled","ordinary_trend_completion_enabled"][..]),
        ("/api/limit-up-ladder","指定日期东方财富涨停梯队",&[][..],&["date","refresh"][..]),
        ("/api/backtest-version","已加载 Rust 引擎与封存执行场景的策略身份",&["run","variant"][..],&[][..]),
        ("/api/backtest-job","已有任务运行或完成结果",&["job"][..],&[][..]),
        ("/api/backtest-jobs","实际任务注册表与持久历史",&[][..],&[][..]),
        ("/api/backtest-preview","已有任务在已完成交易日的预览",&["job","after"][..],&[][..]),
        ("/api/watchlists","持久化自选股与版本（cache=only内存预览，cache=refresh数据库同步）",&[][..],&["cache"][..]),
    ] {
        let parameters=required.iter().chain(optional.iter()).map(|name|json!({"name":name,"in":"query","required":required.contains(name),"schema":{"type":"string"}})).collect::<Vec<_>>();
        let parameters=parameters.into_iter().map(|mut parameter|{match parameter["name"].as_str(){Some("timeframe")=>{parameter["schema"]=json!({"type":"string","enum":["1d","1w","1mo","3mo","1y"]});parameter["description"]=json!("K线周期；每个周期分别计算折线0、一级1、二级2、三级3。");},Some("trend_level")=>{parameter["description"]=json!("旧结构信号筛选参数：1/2/3为实际趋势级别，0是全部趋势级别的兼容哨兵；区别于分析结果level=0的技术折线。");},_=>{}}parameter}).collect::<Vec<Value>>();
        paths.insert(path.into(),json!({"get":{"summary":summary,"parameters":parameters,"responses":{"200":{"description":"请求成功","content":{"application/json":{"schema":{"type":"object"}}}},"202":{"description":"任务仍在运行"},"304":{"description":"ETag 未变化"},"400":{"$ref":"#/components/responses/Invalid"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"description":"资源不存在"},"409":{"description":"版本或请求冲突"},"503":{"$ref":"#/components/responses/Unavailable"}}}}));
    }
    if let Some(path)=paths.get_mut("/health/live"){path["get"]["responses"]=json!({"204":{"description":"进程存活，无响应体"}});}
    for source in ["tdx","akshare"] {
        let parameters=crate::application::backtest_request::REQUIRED.iter().chain(crate::application::backtest_request::OPTIONAL.iter()).map(|name|json!({"name":name,"in":"query","required":crate::application::backtest_request::REQUIRED.contains(name),"schema":{"type":"string"}})).collect::<Vec<_>>();
        paths.insert(format!("/api/{source}-backtest"),json!({"get":{"summary":"真实同源因果复权与 Rust 独立账户回测","description":"HTTP 断开后任务继续；backtest_job 可用于幂等重试和进度读取。complete=false 的结果不进入有效完成缓存。","parameters":parameters,"responses":{"200":{"description":"结构模式为精简TrendAnalysisDto；四级点trendState为入段六态，trendStateKnownIndex省略时等于knownIndex，null表示背景不足；行情从/api/trend-bars读取。账户模式为原账户结果及complete/unavailable_rules"},"400":{"$ref":"#/components/responses/Invalid"},"409":{"description":"任务、股票或策略版本冲突"},"503":{"$ref":"#/components/responses/Unavailable"}}}}));
    }
    paths.insert("/api/v1/users".into(),json!({"post":{"tags":["Users"],"summary":"Create a new user","requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateUser"}}}},"responses":{"201":{"description":"User created","content":{"application/json":{"schema":{"$ref":"#/components/schemas/User"}}}},"400":{"$ref":"#/components/responses/Invalid"},"409":{"description":"Email already registered"},"503":{"$ref":"#/components/responses/Unavailable"}}}}));
    if let Some(path)=paths.get_mut("/api/watchlists"){path["post"]=json!({"summary":"保存、添加、移除或幂等导入自选","requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object","required":["action"],"properties":{"action":{"type":"string","enum":["save","add","remove","import","settings","retry"]},"revision":{"type":"integer","minimum":0},"snapshot":{"type":"object"},"groupId":{"type":"string"},"stocks":{"type":"array","items":{"type":"object"}},"token":{"type":"string"},"settings":{"type":"object"}}}}}},"responses":{"200":{"description":"返回最新自选版本与内容"},"400":{"$ref":"#/components/responses/Invalid"},"409":{"description":"WATCHLIST_CONFLICT"},"413":{"description":"请求超过 4 MiB"},"503":{"description":"存储、策略版本或自动调度依赖不可用"}}});}
    paths.insert("/api/trend-analysis".into(),json!({"post":{"summary":"按 TrendAnalyzer 流程逐 K 线传播四个结构级别","description":"level=0/1/2/3分别为技术折线及一/二/三级趋势，均属于identity.timeframe指定的同一K线周期；例如1w也计算全部四级。complete/unavailableRules表示该前缀计算状态，非验证结论。","requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/AnalysisRequest"}}}},"responses":{"200":{"description":"state、levels、lastExecution、cacheStatus、complete、unavailableRules"},"400":{"$ref":"#/components/responses/Invalid"},"429":{"description":"并发已满"},"504":{"description":"分析超时且已请求取消"}}}}));
    Json(json!({"openapi":"3.1.0","info":{"title":"WaveQuant Rust API","version":env!("CARGO_PKG_VERSION"),"description":"Rust 原生迁移服务。数据JSON响应采用wavequant.indexed.v1节点表，按root及nodes引用读取；本OpenAPI文档仍为标准JSON。调用受loopback Host与Origin白名单约束。"},"paths":paths,"components":{"securitySchemes":{"bearer":{"type":"http","scheme":"bearer","bearerFormat":"JWT"}},"responses":{"Invalid":{"description":"输入无效","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Error"}}}},"Forbidden":{"description":"Host 或 Origin 不允许"},"Unavailable":{"description":"所需真实数据或依赖暂不可用"}},"schemas":{"Error":{"type":"object","required":["error","code"],"properties":{"error":{"type":"string"},"code":{"type":"string"}}},"CreateUser":{"type":"object","required":["name","email"],"properties":{"name":{"type":"string","minLength":1},"email":{"type":"string","format":"email"}}},"User":{"type":"object","required":["id","name","email","createdAt","updatedAt"],"properties":{"id":{"type":"string","format":"uuid"},"name":{"type":"string"},"email":{"type":"string","format":"email"},"createdAt":{"type":"string","format":"date-time"},"updatedAt":{"type":"string","format":"date-time"}}},"AnalysisRequest":{"type":"object","required":["identity","bars"],"additionalProperties":false,"properties":{"identity":{"type":"object","required":["symbol","source_version","adjustment","timeframe"],"properties":{"symbol":{"type":"string"},"source_version":{"type":"string"},"adjustment":{"type":"string"},"timeframe":{"type":"string","description":"独立K线周期身份；与结构level无关。例如1w内仍有level0..3"}}},"bars":{"type":"array","maxItems":250000,"items":{"type":"object","required":["index","time","open","high","low","close","volume"],"properties":{"index":{"type":"integer","minimum":0},"time":{"type":"string"},"open":{"type":"number","exclusiveMinimum":0},"high":{"type":"number","exclusiveMinimum":0},"low":{"type":"number","exclusiveMinimum":0},"close":{"type":"number","exclusiveMinimum":0},"volume":{"type":["string","number"]}}}},"config":{"type":"object"},"state":{"type":["object","null"]}}}}}}))
}
pub async fn page()->Html<&'static str> {Html(r#"<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>WaveQuant Rust API</title><style>body{font:16px system-ui;max-width:1000px;margin:48px auto;padding:0 24px;color:#15263b;background:#f5f7fa}a{color:#1759a8}article{background:white;border:1px solid #d8e0ea;padding:20px;margin:16px 0;border-radius:8px}code{font-size:15px}pre{white-space:pre-wrap;overflow-wrap:anywhere}h1{font-size:30px}</style><h1>WaveQuant Rust API</h1><p>以下列出当前注册的端点与请求字段。完整协议可下载 <a href="/api/docs-json">OpenAPI JSON</a>。</p><main id="endpoints">正在读取接口定义…</main><script>fetch('/api/docs-json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json()}).then(spec=>{const root=document.getElementById('endpoints');root.textContent='';for(const [path,methods] of Object.entries(spec.paths)){for(const [method,operation]of Object.entries(methods)){const card=document.createElement('article');const title=document.createElement('h2');title.textContent=method.toUpperCase()+' '+path;card.append(title);const summary=document.createElement('p');summary.textContent=operation.summary;card.append(summary);const detail=document.createElement('pre');detail.textContent=JSON.stringify(operation,null,2);card.append(detail);root.append(card)}}}).catch(()=>{document.getElementById('endpoints').textContent='接口定义暂不可用，请稍后刷新。'});</script></html>"#)}
